// Collects errors that guarded callbacks report, normalizes them and hands
// them to the listeners (the logging layer in the reference).
const listeners = [];
const history = [];

function normalize(error, metadata) {
  return {
    message: error?.message ?? String(error),
    name: error?.name ?? "Error",
    stack: error?.stack ?? "",
    guard: metadata?.name ?? null,
    depth: metadata?.depth ?? 0,
  };
}

const ErrorPubSub = {
  addListener(listener) {
    listeners.push(listener);
  },
  reportError(error, metadata) {
    const normalized = normalize(error, metadata);
    history.push(normalized);
    if (history.length > 50) {
      history.shift();
    }
    for (const listener of listeners) {
      listener(normalized);
    }
    console.error(error);
  },
  history,
};

export default ErrorPubSub;
