// The event subscription module React's www build attaches its root
// listeners through. Each subscription returns a handle with remove().
function subscribe(target, eventType, listener, options) {
  target.addEventListener(eventType, listener, options);
  return {
    remove() {
      target.removeEventListener(eventType, listener, options);
    },
  };
}

export function listen(target, eventType, listener) {
  return subscribe(target, eventType, listener, false);
}

export function capture(target, eventType, listener) {
  return subscribe(target, eventType, listener, true);
}

export function bubbleWithPassiveFlag(target, eventType, listener, passive) {
  return subscribe(target, eventType, listener, { capture: false, passive });
}

export function captureWithPassiveFlag(target, eventType, listener, passive) {
  return subscribe(target, eventType, listener, { capture: true, passive });
}
